import React, { useState, useEffect } from "react";
import { getExamCounts } from "../services/api";


const ExamCounts = ({ franchiseId }) => {
    const [counts, setCounts] = useState({ today: 0, week: 0, month: 0 });
    const [error, setError] = useState("");

    useEffect(() => {
        const fetchExamCounts = async () => {
            try {
                const countsData = await getExamCounts(franchiseId);
                setCounts(countsData);
            } catch (err) {
                setError(err.message);
            }
        };

        if (franchiseId) {
            fetchExamCounts();
        }
    }, [franchiseId]);

    if (error) {
        return <p>Error: {error}</p>;
    }

    return (
        <div>
            <h2>Exam Counts</h2>
            <p>Today's Exams: {counts.today}</p>
            <p>This Week's Exams: {counts.week}</p>
            <p>This Month's Exams: {counts.month}</p>
        </div>
    );
};

export default ExamCounts;
